        <p style="font-size:.82rem;color:var(--muted);margin:-6px 0 14px">Selecione de 1 a 3 cursos e, para cada um, a modalidade desejada. Não é possível repetir o mesmo curso.</p>
        <div id="inscCursosList">
          <div class="fgrid insc-curso-item" data-index="0">
            <div class="field"><label>Curso desejado <span class="req">*</span></label><select class="insc-curso-sel" required><option value="">Carregando cursos…</option></select></div>
            <div class="field"><label>Modalidade <span class="req">*</span></label><select class="insc-mod-sel" required><option value="">Selecione um curso primeiro</option></select></div>
          </div>
        </div>
        <button type="button" class="btn btn-outline" id="inscAddCurso" style="margin:6px 0 22px"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 5v14M5 12h14"/></svg> ADICIONAR OUTRO CURSO</button>

        <div class="form-sec-title" data-ic="user">DADOS PESSOAIS</div>
        <div class="fgrid"><div class="field"><label>Nome completo <span class="req">*</span></label><input type="text" name="nome_completo" placeholder="Digite seu nome completo" required></div><div class="field"><label>Data de nascimento <span class="req">*</span></label><input type="date" name="data_nascimento" required></div><div class="field"><label>CPF <span class="req">*</span></label><input type="text" name="cpf" placeholder="000.000.000-00" required></div><div class="field"><label>RG</label><input type="text" name="rg" placeholder="00.000.000-0"></div><div class="field"><label>Estado civil</label><select name="estado_civil"><option value="">Selecione</option><option>Solteiro(a)</option><option>Casado(a)</option><option>Viúvo(a)</option><option>Divorciado(a)</option></select></div><div class="field"><label>Naturalidade</label><input type="text" name="naturalidade_cidade" placeholder="Digite sua naturalidade"></div><div class="field"><label>Nacionalidade</label><select name="nacionalidade"><option>Brasileira</option><option>Outra</option></select></div><div class="field"><label>Sexo <span class="req">*</span></label><select name="sexo" required><option value="">Selecione</option><option value="M">Masculino</option><option value="F">Feminino</option><option value="Outro">Outro</option></select></div><div class="field"><label>Telefone / WhatsApp <span class="req">*</span></label><input type="tel" name="telefone" placeholder="(21) 99999-9999" required></div><div class="field"><label>E-mail <span class="req">*</span></label><input type="email" name="email" placeholder="seu@email.com" required></div><div class="field"><label>Logradouro <span class="req">*</span></label><input type="text" name="logradouro" placeholder="Rua, Avenida" required></div><div class="field"><label>Número <span class="req">*</span></label><input type="text" name="numero" placeholder="Nº" required></div><div class="field"><label>Complemento</label><input type="text" name="complemento" placeholder="Apto, bloco, etc."></div><div class="field"><label>Bairro <span class="req">*</span></label><input type="text" name="bairro" placeholder="Digite o bairro" required></div><div class="field"><label>Cidade <span class="req">*</span></label><input type="text" name="cidade" placeholder="Digite a cidade" required></div><div class="field"><label>Estado <span class="req">*</span></label><select name="estado" required><option value="">Selecione</option><option value="RJ">RJ</option><option value="SP">SP</option><option value="MG">MG</option><option value="ES">ES</option></select></div><div class="field"><label>CEP <span class="req">*</span></label><input type="text" name="cep" placeholder="00000-000" required></div></div>

